import{c as a,Q as n,j as s,m as t}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Graph Engineering explained: what it is, when to use it and when not to","description":"","frontmatter":{"url":"https://x.com/AnatoliKopadze/status/2080668775796314331","title":"Graph Engineering explained: what it is, when to use it and when not to","author":"AnatoliKopadze","archived":"2026-07-30T00:00:00.000Z","handle":"@AnatoliKopadze","published":"2026-07-24T00:00:00.000Z","stats":"682 likes · 98 retweets · 2344 bookmarks · 1243551 views","tags":["graph-engineering","fake-edge-test","diamond-pattern","dynamic-workflows","anchors","claude-code"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-24-@AnatoliKopadze-314331.md","filePath":"research/tweets/2026-07-24-@AnatoliKopadze-314331.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-07-24-@AnatoliKopadze-314331.md"};function i(r,e,p,l,h,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="graph-engineering-explained-what-it-is-when-to-use-it-and-when-not-to-—-anatolikopadze" tabindex="-1">Graph Engineering explained: what it is, when to use it and when not to — @AnatoliKopadze <a class="header-anchor" href="#graph-engineering-explained-what-it-is-when-to-use-it-and-when-not-to-—-anatolikopadze" aria-label="Permalink to &quot;Graph Engineering explained: what it is, when to use it and when not to — @AnatoliKopadze&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/AnatoliKopadze/status/2080668775796314331" target="_blank" rel="noreferrer">https://x.com/AnatoliKopadze/status/2080668775796314331</a><strong>作者</strong>：AnatoliKopadze（@AnatoliKopadze） <strong>發布日期</strong>：2026-07-24 <strong>收錄日期</strong>：2026-07-30 <strong>類型</strong>：Twitter Article <strong>統計</strong>：682 likes · 98 retweets · 2344 bookmarks · 1243551 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Most people are using AI at 5 to 10% of what it can actually do. There is a faster way, and it is bigger than it looks. Learn it, and you can optimize enormous processes, not just personal tasks.</p><p>This is the skill behind real roles at large companies. The difference between doing one job, and designing how a hundred of them get done.</p><p>I got lucky with it early. When I studied at one of the best universities in Denmark, we had a whole course on one thing: how to lay a process out as a diagram and make it as efficient as possible.</p><p>Back then it felt abstract. Now it is the exact thing the top AI engineers are arguing about on your timeline.</p><p>By the end of this article you will understand Graph Engineering better than almost anyone you follow: what a graph actually is, the one test that instantly makes your AI faster, the single pattern that pays for itself, where these things quietly break, when a graph is the wrong tool, and how to build a real one yourself in a couple of minutes.</p><hr><p>Before we get into it, follow me on X and join my Telegram channel I just created where I post more AI content every day. Both are free. X - <a href="https://x.com/AnatoliKopadze" target="_blank" rel="noreferrer">https://x.com/AnatoliKopadze</a> Telegram - <a href="https://t.me/kopadzemp" target="_blank" rel="noreferrer">https://t.me/kopadzemp</a></p><hr><h2 id="_1-where-this-even-came-from" tabindex="-1">1 - Where this even came from. <a class="header-anchor" href="#_1-where-this-even-came-from" aria-label="Permalink to &quot;1 - Where this even came from.&quot;">​</a></h2><p>A month ago the whole field was talking about loops. Then Peter Steinberger posted the line above, and a corner of the internet that had just finished learning loops declared them old news overnight.</p><p>The joke landed because it was half true. If you have read my Loops article, you already have the foundation. A loop is one agent improving one thing on repeat: try, check, adjust, go again. That was the skill of last month.</p><p>What everyone moved to is not a better loop. It is a graph of loops, a network where cycles watch and correct each other instead of one agent chasing one number alone.</p><p>And engineers pushed back on the hype within hours, pointing out this is a decades-old idea wearing a new name. They are right, and that is the good news. A pattern that has run critical systems for thirty years is exactly what you want to trust with your work.</p><hr><h2 id="_2-what-a-graph-actually-is" tabindex="-1">2 - What a graph actually is. <a class="header-anchor" href="#_2-what-a-graph-actually-is" aria-label="Permalink to &quot;2 - What a graph actually is.&quot;">​</a></h2><p>A graph is just a plan for your AI work, drawn out so you can see it. It answers two questions: which jobs need to happen, and which job has to wait for which.</p><p>There are only two parts, and getting them straight fixes most of the confusion.</p><p>A box is called a node. It&#39;s one job: one agent doing one task, with one thing going in and one thing coming out. Researching a competitor. Writing a draft. Checking a claim.</p><p>An arrow is called an edge. It just means one job needs what another job produced, so it has to wait for it. And the arrow only counts when something real actually passes along it.</p><p>[圖 1]</p><hr><p>Nodes do the thinking. Edges carry the results. That is the entire vocabulary. Once you have it, you never need a definition again. The thing that makes a node actually usable in a graph is a contract: one bounded job, a defined input, a defined output. A node whose output is a wall of free text is a node only a human can read. A node with a fixed output shape is one the next node can consume without guessing, which is the whole point.</p><hr><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ NODE CONTRACT</span></span>
<span class="line"><span>JOB:     research one competitor&#39;s pricing (one job, nothing else)</span></span>
<span class="line"><span>IN:      { competitor: &quot;name&quot;, url: &quot;https://...&quot; }   ← passed in, never assumed</span></span>
<span class="line"><span>OUT:     { price: number, plan: string, source: url, date: &quot;YYYY-MM-DD&quot; }</span></span>
<span class="line"><span>SCHEMA:  enforced. if the agent returns free text, it&#39;s rejected and retried</span></span>
<span class="line"><span>WHY:     a defined output is what lets the next node read this one</span></span>
<span class="line"><span>         without a human in the middle. that is what makes it wire-able.</span></span></code></pre></div><hr><h2 id="_3-the-test-that-finds-the-fake-edges" tabindex="-1">3 - The test that finds the fake edges. <a class="header-anchor" href="#_3-the-test-that-finds-the-fake-edges" aria-label="Permalink to &quot;3 - The test that finds the fake edges.&quot;">​</a></h2><p>Look at the AI workflow you run today and walk it step by step. At each step, ask one thing: does this step actually need the result of the one before it?</p><p>If yes, the edge is real. Keep the order. If no, there is no edge, and the wait is wasted. Those two jobs can run at the same time.</p><p>Take a simple one: &quot;review file A for bugs, then review file B for bugs.&quot; It reads like a sequence, but the check on file B never looks at what file A returned. They only run one after another because that is the order you typed them in. Run them side by side and the whole thing finishes in the time of the slower single file, not the two added together.</p><p>You will find two or three of these fake edges in almost any workflow you draw. Every one of them is time you are throwing away for free.</p><hr><p>[圖 2]</p><hr><h2 id="_4-your-current-setup-is-already-a-graph" tabindex="-1">4 - Your current setup is already a graph. <a class="header-anchor" href="#_4-your-current-setup-is-already-a-graph" aria-label="Permalink to &quot;4 - Your current setup is already a graph.&quot;">​</a></h2><p>When you write an agent as &quot;do A, then B, then C, then D,&quot; you have technically already drawn a graph. It is just the saddest possible one: a single straight chain where every node has one arrow in and one arrow out. It runs correctly. It also runs slowly and breaks easily, because a chain has no redundancy. If C stalls, D never happens, and A&#39;s work is trapped upstream with nowhere to go. The first real skill of graph engineering is redrawing that chain. Take your linear workflow, and for each arrow, ask the fake-edge question. Cut the arrows that carry no data, and the line collapses into something wider: a few independent jobs that can all run at once, feeding one job that needs them all. The reason this matters is not cosmetic. A linear workflow with 40 steps has 40 points of sequential failure and the latency of all 40 added together. The same 40 jobs drawn as a graph have only as many real dependencies as actually exist, usually three to five, and finish at the speed of your slowest layer, not the sum of everything. That is the difference between a job that takes five minutes and one that takes fifteen seconds, running the exact same work. The model was never the bottleneck. The line you drew was.</p><hr><h2 id="_5-the-one-pattern-that-pays-the-diamond" tabindex="-1">5 - The one pattern that pays: the diamond. <a class="header-anchor" href="#_5-the-one-pattern-that-pays-the-diamond" aria-label="Permalink to &quot;5 - The one pattern that pays: the diamond.&quot;">​</a></h2><p>You do not need a hundred shapes. Watch any serious agent system work and the same picture keeps appearing. The work splits, several workers dig side by side, something checks what they found, and everything merges back into one answer. That picture is called the diamond, and it is close to the only pattern you need this year. Its formal name is worth memorizing: fan out, reduce, synthesize.</p><p>Fan out to gather breadth, reduce with plain code to compress it, synthesize with a final agent to write the answer.</p><hr><p>[圖 3]</p><hr><p>The research feature inside Claude runs exactly this in production. One lead plans the angles, workers gather in parallel, findings get checked, and only then does one report reach you. Once you can see the diamond, you stop asking &quot;how do I make my agent do more steps&quot; and start asking &quot;where is the split, where is the merge.&quot; That second question is the one that scales. Here is what the diamond actually looks like under the hood. When you say &quot;workflow,&quot; Claude writes a short script like this itself and runs the coordination as code, which is why passing results between agents costs zero extra context.</p><hr><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// a market-scan graph — the diamond, written by Claude when you say &quot;workflow&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const angles = [</span></span>
<span class="line"><span>  &quot;pricing vs the top 3 competitors&quot;,</span></span>
<span class="line"><span>  &quot;what buyers complain about in reviews&quot;,</span></span>
<span class="line"><span>  &quot;the feature gaps in the category&quot;,</span></span>
<span class="line"><span>  &quot;where the market moves in the next 12 months&quot;,</span></span>
<span class="line"><span>];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// FAN OUT — one researcher per angle, all at the same time</span></span>
<span class="line"><span>const raw = await parallel(</span></span>
<span class="line"><span>  angles.map(a =&gt; () =&gt; agent({</span></span>
<span class="line"><span>    task: \`research: \${a}. every claim needs a source url + date.\`,</span></span>
<span class="line"><span>    schema: Finding,        // validated output, not free text</span></span>
<span class="line"><span>    model: &quot;cheap&quot;,         // boring node → cheap model</span></span>
<span class="line"><span>  }))</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// REDUCE — plain code, no model, no tokens</span></span>
<span class="line"><span>const findings = dedupeBySource(raw.flat().filter(Boolean));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// VERIFY — a FRESH skeptic per finding, tries to kill it</span></span>
<span class="line"><span>const survivors = await parallel(</span></span>
<span class="line"><span>  findings.map(f =&gt; () =&gt; agent({</span></span>
<span class="line"><span>    task: &quot;try to disprove this. return keep | drop + why.&quot;,</span></span>
<span class="line"><span>    input: f,</span></span>
<span class="line"><span>    freshContext: true,     // never reuse the researcher&#39;s chat</span></span>
<span class="line"><span>    model: &quot;strong&quot;,        // judgment node → strong model</span></span>
<span class="line"><span>  }))</span></span>
<span class="line"><span>).then(v =&gt; findings.filter((_, i) =&gt; v[i].verdict === &quot;keep&quot;));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// SYNTHESIZE — one agent writes the answer from what survived</span></span>
<span class="line"><span>return agent({ task: &quot;one report, ranked by confidence, sources attached.&quot;,</span></span>
<span class="line"><span>               input: survivors, model: &quot;strong&quot; });</span></span></code></pre></div><hr><p>Read it once and the whole craft is visible: the fan-out where work is independent, the reduce done in free code, the verify on a fresh context, cheap models on the boring nodes and the strong one where judgment lives and a single synthesize at the end. Same skeleton behind a market scan, a code review, or a research report. Swap the angles and the prompts.</p><hr><h2 id="_6-the-checker-is-the-whole-trick" tabindex="-1">6 - The checker is the whole trick. <a class="header-anchor" href="#_6-the-checker-is-the-whole-trick" aria-label="Permalink to &quot;6 - The checker is the whole trick.&quot;">​</a></h2><p>Now the part almost everyone skips, and it is what separates a real graph from an expensive toy.</p><p>Every serious test of AI self-review says the same thing: models miss most of their own mistakes. A model grading its own work is far too easy on itself.</p><p>So you never let the agent that did the work check the work.</p><p>You put a separate node on the edge. Its only job is to try to kill the finding before it moves on. If it survives, it passes. If not, it dies right there.</p><p>Here is the catch nobody names: that checker needs a clean context.</p><p>Give it the same chat the worker had and it is not checking anything, it is nodding along to itself in a different font. A graph of agents sharing one context is just a single loop in a costume, and it breaks the same way, only later and pricier.</p><p>So make the verifier fresh. Own context. Checking a real signal, not &quot;did the agent say it is done&quot; but &quot;does the test actually pass.&quot;</p><p>Then split the checking three ways. Is it correct? Is it current? Is the source even real? Three different lenses catch what ten identical ones miss.</p><hr><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ VERIFIER NODE</span></span>
<span class="line"><span>INPUT:    one finding from a worker (the finding only, never the worker&#39;s chat)</span></span>
<span class="line"><span>CONTEXT:  fresh and empty. it has not seen the work it is judging</span></span>
<span class="line"><span>CHECKS:   three skeptics run in parallel, each with a different question</span></span>
<span class="line"><span>  1. is it correct?      → does the claim actually hold up</span></span>
<span class="line"><span>  2. is it current?      → is the source recent, not something stale</span></span>
<span class="line"><span>  3. is the source real? → does the link resolve to the claim it&#39;s cited for</span></span>
<span class="line"><span>PASS:     keep the finding only if a majority of skeptics let it live</span></span>
<span class="line"><span>FAIL:     drop it before it ever reaches the final answer</span></span></code></pre></div><hr><p>The rule to remember: a worker and its verifier must never share a context. The moment they do, you are back to one loop grading its own homework, just with a bigger bill.</p><hr><h2 id="_7-where-graphs-actually-break" tabindex="-1">7 - Where graphs actually break. <a class="header-anchor" href="#_7-where-graphs-actually-break" aria-label="Permalink to &quot;7 - Where graphs actually break.&quot;">​</a></h2><hr><ol><li>Context collapse. Fan out a thousand nodes, then try to feed all thousand outputs into one final step, and you blow past the context window before synthesis even starts. The fix: layer your fan-in. Batch the results, summarize each batch, then combine the summaries, never the raw pile.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// layered fan-in — never pour 1,000 raw outputs into one step</span></span>
<span class="line"><span>const batches = chunk(results, 40);              // groups of 40</span></span>
<span class="line"><span>const summaries = await parallel(</span></span>
<span class="line"><span>  batches.map(b =&gt; () =&gt; agent({ task: &quot;summarize this batch&quot;, input: b }))</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>return agent({ task: &quot;write the answer from the summaries&quot;, input: summaries });</span></span>
<span class="line"><span>// the final step reads ~25 summaries, not 1,000 raw outputs</span></span></code></pre></div><hr><ol start="2"><li>False independence. Two nodes look independent because their prompts never mention each other, but they both write to the same file or hit the same rate-limited API. That is a hidden edge.</li></ol><p>When Bun&#39;s team first fanned a big job across many agents, they shared one workspace and overwrote each other.</p><p>The fix: give every worker its own isolated space, and audit for shared resources, not just shared data.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// isolate the workers — no shared file, no shared workspace</span></span>
<span class="line"><span>await parallel(files.map(f =&gt; () =&gt; agent({</span></span>
<span class="line"><span>  task: \`refactor \${f}\`,</span></span>
<span class="line"><span>  worktree: true,        // each agent works in its own git worktree</span></span>
<span class="line"><span>})));</span></span>
<span class="line"><span>// they can&#39;t overwrite each other, then the results merge cleanly</span></span>
<span class="line"><span>// rule: any two nodes writing the same file need an edge, not parallelism</span></span></code></pre></div><hr><ol start="3"><li>Silent node failure. In a chain, one failure stops everything, annoying but obvious. In a graph, one dead node among two hundred can slip into a report that looks complete.</li></ol><p>The fix: every merge step counts its inputs against the number it expected, and flags the gap instead of quietly running on half the data.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// fan-in guard — catch the node that quietly died</span></span>
<span class="line"><span>const results = (await parallel(jobs)).filter(Boolean);   // dropped nodes = null</span></span>
<span class="line"><span>if (results.length &lt; jobs.length) {</span></span>
<span class="line"><span>  flag(\`WARNING: \${jobs.length - results.length} of \${jobs.length} nodes returned nothing\`);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// never synthesize on a partial set and call the report complete</span></span></code></pre></div><hr><h2 id="_8-do-you-even-need-one" tabindex="-1">8 - Do you even need one? <a class="header-anchor" href="#_8-do-you-even-need-one" aria-label="Permalink to &quot;8 - Do you even need one?&quot;">​</a></h2><p>As tradition goes for my articles, let&#39;s honestly figure out who this could even be useful for.</p><p>A graph buys breadth. It does not buy better judgment.</p><p>It is a tool for width, for independent work done at once. When the work is not wide, the line was never the problem.</p><hr><p>Skip the graph when:</p><ul><li><p>The task is small or isolated. Adding one function, fixing one bug. The coordination is pure overhead, and a single agent is faster and cheaper.</p></li><li><p>You want to approve every step. A graph&#39;s whole point is running wide without you, so a tight leash works against it.</p></li><li><p>You do not know yet what you are looking for. Exploratory work wants one agent you can steer, not a fleet locked into a plan.</p></li><li><p>The steps genuinely depend on each other. Forcing a graph onto truly sequential work just adds cost for zero speedup.</p></li><li><p>The tell is the fake-edge test. If you cannot find two jobs with no edge between them, there is no graph to build. It is a loop, and a loop is fine.</p></li></ul><hr><h2 id="_9-the-part-nobody-wants-to-hear-anchors" tabindex="-1">9 - The part nobody wants to hear: anchors. <a class="header-anchor" href="#_9-the-part-nobody-wants-to-hear-anchors" aria-label="Permalink to &quot;9 - The part nobody wants to hear: anchors.&quot;">​</a></h2><p>There is a deeper trap here, and it is the real lesson of this whole shift.</p><p>Imagine you build the full graph. Paired checkers, audit nodes, meta-nodes tuning the other nodes. Every node watches another node, and every one of them reads a report.</p><p>The audit checks the numbers against the finance numbers, which came from the same system in the first place.</p><p>Everything is consistent. Nothing is verified.</p><p>This graph fails exactly like the single loop did, just later, more expensively, and with far more green lights on the way down.</p><hr><p>[圖 4]</p><hr><p>Topology alone does not buy truth. The graph needs anchors: nodes that cannot be argued with.</p><p>Tests that actually ran, not &quot;should pass,&quot; did pass. Revenue that landed in the bank. Customers who actually stayed.</p><p>And some rules must be frozen, the ones an optimizer would be tempted to weaken, kept off-limits precisely because they are the ones it would bend to win.</p><p>The graph is only as honest as the things inside it that refuse to move.</p><p>Judge it on numbers that cannot argue back and it stays grounded. Let it grade its own reports and it will be confidently wrong.</p><hr><h2 id="_10-build-one-yourself-in-claude-code" tabindex="-1">10 - Build one yourself in Claude Code. <a class="header-anchor" href="#_10-build-one-yourself-in-claude-code" aria-label="Permalink to &quot;10 - Build one yourself in Claude Code.&quot;">​</a></h2><p>Enough theory. If you have decided this is for you, or you just want to try it, let&#39;s build one. You can build a real graph in a couple of minutes, because Claude Code shipped the tooling to do it directly, called dynamic workflows. It comes down to one word: &quot;workflow.&quot;</p><p>Put it in your prompt and Claude stops working through a single line of steps. Instead it writes a short orchestration script, then spawns a coordinated fleet of sub-agents to run it.</p><p>The important part is that the coordination is code, not a conversation. Passing results between agents does not re-spend your context the way a chat handoff does, which is what lets one run scale to a whole fleet without drowning the session.</p><p>Open a real repository you know, and paste this:</p><hr><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ GRAPH SPEC</span></span>
<span class="line"><span>GOAL: audit every route file under src/routes/ for missing auth checks</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FAN OUT:    one agent per file, all running in parallel</span></span>
<span class="line"><span>VERIFY:     an independent checker on each finding, with fresh context</span></span>
<span class="line"><span>CAP:        20 files on this first run</span></span>
<span class="line"><span>ON FAIL:    flag any file that doesn&#39;t return, never skip it silently</span></span>
<span class="line"><span>REPORT:     one merged list of the routes missing auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(start the prompt with the word &quot;workflow&quot; so Claude builds the graph)</span></span></code></pre></div><hr><p>Run it, and here is what happens.</p><p>First, Claude signals that it is building a workflow instead of answering in a normal chat, and shows you the plan before doing anything. You read it and approve.</p><p>Then the fleet runs. One agent per file, all at the same time, while your own session stays free the whole way through.</p><p>And what lands at the end is not twenty separate chats to dig through. It is one report. The in-between results lived inside the script, never in your context, so the only thing you actually see is the final answer.</p><p>That is a graph. A dozen agents from a single sentence. When a run comes out good, save it, and it turns into one command you can re-run by name forever.</p><hr><p>[圖 5] Notice the &quot;20 files&quot; cap in that prompt. It keeps your first run cheap, and it hints at the thing every demo leaves out: the bill.</p><hr><h2 id="_11-ready-graphs-you-can-paste-right-away" tabindex="-1">11 - Ready graphs you can paste right away. <a class="header-anchor" href="#_11-ready-graphs-you-can-paste-right-away" aria-label="Permalink to &quot;11 - Ready graphs you can paste right away.&quot;">​</a></h2><p>Every one of these is the same diamond aimed at a different job. Open Claude Code in a real folder, swap the bracketed parts for your own, and paste. The word &quot;workflow&quot; is what tells Claude to build a coordinated fleet instead of a single line of steps. Keep yourself as the last yes before anything ships.</p><hr><p>A decision-grade research desk. Replaces a week of googling or an expensive analyst invoice. Your question splits into angles, researchers dig at once, a skeptic attacks every finding, and only the survivors reach the report.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ GRAPH SPEC</span></span>
<span class="line"><span>GOAL: decision-grade research on [your question]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FAN OUT:      split into 5 distinct angles, one researcher per angle, in parallel</span></span>
<span class="line"><span>RULE:         every finding needs a source link and a date</span></span>
<span class="line"><span>VERIFY:       a skeptic attacks each finding and tries to disprove it, drop what fails</span></span>
<span class="line"><span>MERGE:        survivors into one report ranked by confidence</span></span>
<span class="line"><span>SAVE:         research-report.md, then show me the top findings</span></span>
<span class="line"><span>HUMAN GATE:   change nothing after that without asking me</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(start the prompt with the word &quot;workflow&quot; so Claude builds the graph)</span></span></code></pre></div><hr><p>An SEO content machine. Writes one ranking-ready draft per run, and never publishes without you.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ GRAPH SPEC</span></span>
<span class="line"><span>GOAL: one ranking-ready draft for [topic]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PARALLEL JOBS (run at once):</span></span>
<span class="line"><span>  1. what the current top-ranking pages cover</span></span>
<span class="line"><span>  2. the real questions people ask about this topic</span></span>
<span class="line"><span>  3. what those top pages skip</span></span>
<span class="line"><span>MERGE:        the three into an outline, then write a full draft</span></span>
<span class="line"><span>VERIFY:       a fact-checker that flags every claim without a source</span></span>
<span class="line"><span>SAVE:         drafts/ with the flagged claims listed at the top</span></span>
<span class="line"><span>HUMAN GATE:   never publish anything</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(start the prompt with the word &quot;workflow&quot; so Claude builds the graph)</span></span></code></pre></div><hr><p>A go-to-market kit. The full launch pack in one run, with you approving every piece.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ GRAPH SPEC</span></span>
<span class="line"><span>GOAL: full launch kit for [product], aimed at [audience]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PARALLEL JOBS (research, run at once):</span></span>
<span class="line"><span>  1. profile the buyer and the exact words they use</span></span>
<span class="line"><span>  2. map where these buyers spend time online</span></span>
<span class="line"><span>  3. collect how competitors pitch them</span></span>
<span class="line"><span>MERGE:        a one-page positioning doc</span></span>
<span class="line"><span>HUMAN GATE:   pause and show me the positioning doc before writing</span></span>
<span class="line"><span>PARALLEL JOBS (writing, from that doc):</span></span>
<span class="line"><span>  1. landing page copy</span></span>
<span class="line"><span>  2. a week of launch posts</span></span>
<span class="line"><span>  3. a set of outreach messages</span></span>
<span class="line"><span>VERIFY:       a checker compares every asset to the positioning doc, flags anything off</span></span>
<span class="line"><span>SAVE:         launch-kit/, change nothing after that without asking me</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(start the prompt with the word &quot;workflow&quot; so Claude builds the graph)</span></span></code></pre></div><hr><p>A refactor sweep across a whole repo. Breadth no single context could hold.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ GRAPH SPEC</span></span>
<span class="line"><span>GOAL: find every function over 100 lines and propose a refactor for each</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FAN OUT:    one agent per file, in parallel</span></span>
<span class="line"><span>VERIFY:     an independent checker on each proposed refactor, fresh context</span></span>
<span class="line"><span>DEDUPE:     proposals against everything already seen</span></span>
<span class="line"><span>CAP:        50 files on this first run</span></span>
<span class="line"><span>REPORT:     how many files came back, so nothing fails silently</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(start the prompt with the word &quot;workflow&quot; so Claude builds the graph)</span></span></code></pre></div><hr><p>A discovery loop of unknown size. For jobs where you do not know how big the work is until you are in it, like a bug sweep where finding one bug reveals three more.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ GRAPH SPEC</span></span>
<span class="line"><span>GOAL: hunt this repo for [security issues / broken error handling / dead code]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FAN OUT:    run finders in parallel</span></span>
<span class="line"><span>DEDUPE:     check each new find against everything already seen</span></span>
<span class="line"><span>VERIFY:     an independent checker on the survivors</span></span>
<span class="line"><span>LOOP:       keep going until two rounds in a row find nothing new, then stop</span></span>
<span class="line"><span>CAP:        a hard limit on total agents so it can&#39;t run away</span></span>
<span class="line"><span>REPORT:     final list ranked by severity</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(start the prompt with the word &quot;workflow&quot; so Claude builds the graph)</span></span>
<span class="line"><span>Run one scoped, watch what it costs, then widen. When a run is good, save it, and every one of these becomes a single command you launch by name.</span></span></code></pre></div><hr><h2 id="_12-the-cost-and-the-supervision" tabindex="-1">12 - The cost and the supervision. <a class="header-anchor" href="#_12-the-cost-and-the-supervision" aria-label="Permalink to &quot;12 - The cost and the supervision.&quot;">​</a></h2><p>A graph costs more than a normal chat. A lot more. The coordination is what gets cheaper, not the work itself. The agents still burn tokens, and a fleet of them burns a pile.</p><p>The clearest example is public. An engineer used this exact setup to rewrite the Bun runtime, translating around 535,000 lines of one language into over a million lines of another in about eleven days. By hand that is close to a year of work.</p><p>It ran about 50 workflows, with up to 64 agents going at once.</p><p>It also cost roughly $165,000 in usage, needed a human designing and watching the whole thing, and got real criticism over whether that much AI-written code can even be reviewed safely.</p><p>That is the honest shape of it. A graph can fan out to a thousand agents and chew through a job no single context could hold. It can also quietly spend your money in the background if you point it at the wrong task or skip the anchors.</p><p>So the heavy version is for teams with the budget, the caps, and the monitoring to run it. If that is not you yet, you are not missing anything. Start small, watch what a run costs, and go wider only once one has earned it.</p><hr><h2 id="_13-what-this-actually-means-for-you" tabindex="-1">13 - What this actually means for you. <a class="header-anchor" href="#_13-what-this-actually-means-for-you" aria-label="Permalink to &quot;13 - What this actually means for you.&quot;">​</a></h2><p>That is the whole picture. You now know what a graph is, where it shines, where it breaks, and who it is actually for.</p><p>You know the strength: breadth, independent work done at once. And the weakness: it buys width, not judgment, and it will spend your money if you point it at the wrong job.</p><p>So the move is not to graph everything. It is to know when the work is wide enough to need one, and when a simple loop was the answer all along.</p><p>My take: learn the fake-edge test tonight. Draw your current workflow, find the edges that carry no data, and delete them. That one move makes you faster than most people before you touch a single new tool.</p><p>Most will keep queueing steps in a line. The few who learn to draw the graph will run a fleet.</p><hr><p>If you want to stay up to date with everything happening in AI, follow me on X and Telegram:</p><p>X - <a href="https://x.com/AnatoliKopadze" target="_blank" rel="noreferrer">https://x.com/AnatoliKopadze</a></p><p>Telegram - <a href="https://t.me/kopadzemp" target="_blank" rel="noreferrer">https://t.me/kopadzemp</a></p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Graph Engineering 全面教學——用「fake-edge test」揪出虛假序列依賴、diamond pattern（fan out→reduce→synthesize）是唯一常用形狀、verifier 必須用全新 context 才不是自我背書、三種常見破圖模式（context collapse/false independence/silent node failure）與修法、以及最關鍵的「anchors」概念（拒絕被說服的真值錨點），並附 Claude Code dynamic workflows 的可直接貼上樣板。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Fake-edge test</strong>：對每個看似循序的步驟問「這步真的需要上一步的結果嗎？」不需要就是假邊，可平行化；文中舉例「review file A 再 review file B」看似循序，實際上互不依賴，平行跑可將耗時從加總變成取最慢單項</li><li><strong>Node contract</strong>：每個節點是有明確 IN/OUT schema 的單一工作，輸出若是自由文字只有人類能讀，強制 schema 才能讓下一節點無需猜測地消費</li><li><strong>Diamond pattern（fan out → reduce → synthesize）</strong>：幾乎是唯一需要記住的形狀——平行蒐集廣度、用純程式碼（非模型）壓縮去重、最後單一 agent 綜合寫出答案；對應到 Claude 官方 research 功能的實際架構</li><li><strong>Verifier 必須全新 context</strong>：讓做工作的 agent 自我審核等於「自己給自己背書」；checker 必須是全新、乾淨、未見過 worker 對話的獨立節點，且應拆成三種互斥角度（正確性/時效性/來源真實性）多數決通過</li><li><strong>三種常見破圖模式</strong>：① Context collapse（千個輸出直接塞進最後一步爆 context，修法：分批摘要再分批合併）② False independence（節點看似獨立實際共寫同一檔案或撞同一 rate-limited API，修法：worktree 物理隔離）③ Silent node failure（死掉的節點在大量節點中被悄悄忽略，修法：merge 步驟強制核對輸入數量與預期數量，缺口要 flag）</li><li><strong>Anchors（錨點）</strong>：純拓撲不保證真相——若所有查核節點的真值來源都來自同一系統，全部一致但全部未被真正驗證；圖需要「拒絕被說服」的錨點（真的跑過的測試、真的進帳的營收、真的留下的客戶），且某些規則必須凍結不可被 optimizer 為了贏而放寬</li><li><strong>何時不該建圖</strong>：任務小/孤立、想每步都核准、還不知道要找什麼（探索性工作）、步驟真的循序依賴——四種情境下該用 loop 而非 graph；判準同樣是 fake-edge test：找不到兩個無邊互斥的工作，就沒有圖可建</li><li><strong>Claude Code dynamic workflows</strong>：prompt 以「workflow」開頭觸發，Claude 自己寫協調腳本並派發 sub-agent 艦隊，協調本身是程式碼不佔用 context，附五組可直接貼上的 GRAPH SPEC 樣板（研究、SEO、GTM、重構、探索性 bug 掃描）</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Bun runtime 遷移案例：約 53.5 萬行代碼移植超過 100 萬行，11 天內完成，跑約 50 個 workflow、最多同時 64 個 agent，成本約 $165,000（與 @undefinedKi 前一篇引用同一案例，數字一致）</li><li>Claude Code dynamic workflows：以「workflow」關鍵字觸發，協調層走程式碼不佔用對話 context</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>引用同一 Bun 遷移案例（$165,000、11 天、50 workflows、64 agents）與本批次先前 @undefinedKi 文章數字一致，可視為社群內同一事件的交叉引用而非獨立驗證，未附官方原始連結，證據品質仍受限於轉述</li><li>「anchors」概念與本 workspace <code>loop.md §L4</code>（oracle 資格與偏差排查）「壞 oracle 比沒有更糟」精神完全對應，且更進一步指出「所有 verifier 共用同一系統真值來源」的隱性失效模式，是本 workspace 現有規則未明確點名的具體風險場景</li><li>Ready-to-paste 的 GRAPH SPEC 樣板與本 session 實際可用的 <code>Workflow</code> 工具（<code>agent()</code>/<code>parallel()</code>/<code>pipeline()</code>）高度對應（fan-out/reduce/synthesize、verifier fresh context、fan-in guard、worktree 隔離），可作為既有 <code>graph.md</code> 與 Workflow 工具說明的外部交叉驗證與範例補充來源</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>五組 ready-to-paste GRAPH SPEC 樣板與本 session Workflow 工具的實際 API 高度對應，可直接參照使用</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>Fake-edge test 與 anchors 概念具體且銳利，補充既有 oracle 資格討論的新場景（共用真值來源的隱性失效）</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>引用具體數字（與另一篇同案例交叉印證），但未附官方原始連結，社群推文上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>完整程式碼範例（fan-out/reduce/synthesize、verifier isolation、fan-in guard、worktree 隔離），與 Workflow 工具 API 對應</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>五組樣板橫跨研究/SEO/GTM/重構/安全掃描，跨任務類型通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.85/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：Ready-to-paste GRAPH SPEC 樣板可直接作為本 workspace 使用 Workflow 工具時的參考範例；「anchors」概念建議評估補充進 <code>loop.md §L4</code> oracle 資格段落（共用真值來源的隱性失效場景），本次先歸檔待後續整合。</p>`,168)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
